/** Resolve the actual Steam CSS-module token already present in the
 * compiled Midnight CSS. No guessing about minified class hashes in CEF.
 *
 * The mapping is generated by the frontend's existing findClassModule()
 * compiler; it is safely passed to the Steam CEF observation script.
 * If a module isn't loaded, fall back to the readable semantic token.
 */
export type NativeCompactAnchor="hero"|"playbar"|"playsection"|"playbutton"|"title"|"sections";
const names:Record<NativeCompactAnchor,string>={
  hero:"sharedappdetailsheader_TopCapsule",
  playbar:"appdetailsplaysection_PlayBar",
  playsection:"basicappdetailssectionstyler_PlaySection",
  playbutton:"appactionbutton_PlayButtonContainer",
  title:"sharedappdetailsheader_TitleSection",
  sections:"appdetailssection_SectionHeader",
};
export type NativeCompactHints=Record<NativeCompactAnchor,string>;

export function nativeCompactHintsFromCss(css:string):NativeCompactHints{
  const output={} as NativeCompactHints;
  for(const key of Object.keys(names) as NativeCompactAnchor[]){
    const semantic=names[key];
    // Matched shape emitted by expandThemeClassAliases:
    // :is([class*="sharedappdetailsheader_TopCapsule"],[class~="_nativeHash"])
    const anchor='[class*="'+semantic+'"],[class~="';
    const at=css.indexOf(anchor);
    const match=at>=0?
      css.slice(at+anchor.length).match(/^([A-Za-z0-9_-]{3,150})"\]/):null;
    output[key]=match?.[1]??"";
  }
  return output;
}

/** No arbitrary JS interpolation: all names are class tokens from the
 * validated alias compiler, and the JSON string is escaped. */
export function compactHintsInjection(hints:NativeCompactHints):string{
  return 'window.__gameLibraryNativeCompactHints14='+JSON.stringify(hints)+';';
}
